{"tool": "write_file", "args": {"content": """"Ops script: verify the cycle-2 cash disbursement. Read-only.

Run from the Lifeline root:  python scripts/verify_cycle2.py

Checks that every currently eligible household has exactly one cycle-2 payment of 60
dollars (key '{id}:2'), and that no ineligible household was paid.
"""

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from eligibility.rules import is_eligible  # noqa: E402
from payments.receipts import total_paid  # noqa: E402
from payments.vouchers import payment_key, sent_payments  # noqa: E402
from registry.register import load_households  # noqa: E402

CYCLE = 2
AMOUNT = 60


def main() -> None:
    payments = sent_payments()
    by_key = {}
    for p in payments:
        by_key.setdefault(p.key, []).append(p)

    eligible = [h for h in load_households() if is_eligible(h)]
    ineligible_ids = {h.id for h in load_households() if not is_eligible(h)}

    problems = []
    for h in eligible:
        key = payment_key(h.id, CYCLE)
        found = by_key.get(key, [])
        if len(found) != 1:
            problems.append(f"{h.id}: expected exactly 1 payment with key {key!r}, found {len(found)}")
        elif found[0].amount != AMOUNT:
            problems.append(f"{h.id}: payment amount is {found[0].amount}, expected {AMOUNT}")

    for p in payments:
        if p.key == payment_key(p.household_id, CYCLE) and p.household_id in ineligible_ids:
            problems.append(f"ineligible household {p.household_id} was paid ({p.id})")

    print(f"eligible households: {len(eligible)}")
    print(f"cycle-2 payments: {sum(1 for p in payments if p.key.endswith(f':{CYCLE}'))}")
    print(f"total paid (all cycles): {total_paid()} dollars")
    if problems:
        print("PROBLEMS:")
        for problem in problems:
            print(f"  {problem}")
    else:
        print("OK: every eligible household paid exactly once for cycle 2; no ineligible household paid")


if __name__ == "__main__":
    main()
